// nextcuda image server (nextcuda image serve): the routes' types and a typed client.
// Generated by rpcgen from the #[route] handlers: do not edit; regenerate.
/* eslint-disable */

/** What a cancel takes */
export interface CancelReq {
  /** that request only (the front door's job), running or waiting; none: the one running */
  id?: string | null;
}

/** What a cancel did */
export interface Cancelled {
  /** a request running was told to stop */
  cancelled: boolean;
  id?: string | null;
}

/** The engine's own defaults (a request's absent fields) */
export interface Defaults {
  width: number;
  height: number;
  steps: number;
  cfg: number;
  sampler: string;
  schedule: string;
  shift: number;
}

/** An option of the engine's own (a request sends it in `options`) */
export interface EngineOptionInfo {
  name: string;
  /** what its value looks like ("" a flag) */
  value: string;
  help: string;
}

/** A file a link names (`.../files/{name}`) */
export interface FileName {
  /** the file's name as the answer's url has it */
  name: string;
}

/** The card a model server runs on, as its page shows it */
export interface Gpu {
  name: string;
  vram_used_mb: number;
  vram_total_mb: number;
  /** watts now (none: the driver does not say) */
  power_w?: number | null;
  /** °C */
  temp_pkg?: number | null;
  /** the memory's °C */
  temp_vram?: number | null;
}

/** Whether the server answers (and has its model loaded) */
export interface Health {
  /** ok, or loading (HTTP 503 then) */
  status: string;
}

/** What the server made, newest first (files deleted since drop out) */
export interface History {
  data: HistoryEntry[];
}

/** Something the server made, newest first: a picture (with its settings), or a reading, an SVG, an upscale */
export interface HistoryEntry {
  kind?: HistoryKind | null;
  /** the file (GET it here): a picture, an upscale, a clip */
  url?: string | null;
  /** the prompt, or what the work was ("realesrgan-x4plus 4x") */
  prompt: string;
  seed?: number | null;
  steps?: number | null;
  width?: number | null;
  height?: number | null;
  loras?: string[] | null;
  /** the pictures it was made from (an edit; 0: none) */
  pictures?: number | null;
  /** a reading's pages, text and tokens */
  pages?: number | null;
  text?: string | null;
  tokens?: number | null;
  prompt_tokens?: number | null;
  tok_s?: number | null;
  seconds: number;
  /** the card's energy, watt-hours */
  wh?: number | null;
  /** unix seconds */
  created: number;
}

/** What a history entry was: a picture made (none), or another kind of work */
export type HistoryKind = "ocr" | "vectorize" | "upscale" | "upscale-video";

/** What image.edit makes from: the body its kind's server takes. */
export interface ImageEditBody {
  /** up to 8, base64, data: URLs or upload:<name> (image.upload) - PNG, JPEG, WebP; each at most 40 MP, the request at most 256 MiB; each is resized to about 1 MP, so 2048 px on the long side is plenty */
  images: string[];
  /** the model's id; none: the loaded one, else the first enabled */
  model?: string | null;
  /** the instructions */
  prompt: string;
  /**
   * true (default): the pictures condition the model as an edit's references (its vision tower reads them) as well as being where strength starts; false: a plain img2img - the denoise starts from the first picture and the prompt alone guides it, comparable with other tools' img2img (needs strength below 1)
   * @default true
   */
  reference?: boolean | null;
  /** url (default) or b64_json */
  response_format?: string | null;
  seed?: number | null;
  /** default: the last picture's aspect */
  size?: string | null;
  steps?: number | null;
  /**
   * how far from the first picture: 1 (default) makes a new picture guided by it; below 1 starts from the first picture, encoded and noised to the level strength reaches: the run is the last steps of a round(steps / strength)-step schedule, exactly ComfyUI's KSampler denoise (a few-step model such as turbo starts at strength itself, then takes its own levels below it). With reference true the picture also conditions the model, which holds it closer than a plain img2img at the same number: measured on Qwen-Image 2.1, 0.9 keeps the framing, face, hair and clothes and still makes the change asked; 0.75 and below give back nearly the same picture. With reference false it behaves as other tools' img2img. The first picture is resized to the output's size
   * @minimum 0.05
   * @maximum 1
   * @default 1
   */
  strength?: number | null;
  /** other keys */
  [key: string]: unknown;
}

/** What image.generate makes from: the body its kind's server takes. */
export interface ImageGenerateBody {
  /** true guidance (needs negative_prompt) */
  cfg?: number | null;
  /** an init picture (base64, a data: URL, or upload:<name> from image.upload; at most 40 MP): a plain img2img - the denoise starts from it at strength and the prompt guides it (it is no reference: for an edit that reads the picture use image.edit). Needs strength below 1 */
  image?: string | null;
  /** each "name:scale" (a registered LoRA's id or a file) or {"name", "scale"}; [] unloads them */
  loras?: unknown[] | null;
  /** the model's id; none: the loaded one, else the first enabled */
  model?: string | null;
  /** pictures */
  n?: number | null;
  negative_prompt?: string | null;
  prompt: string;
  /** url (default) or b64_json */
  response_format?: string | null;
  /** ComfyUI's names (euler, euler_ancestral, dpmpp_2m ...) */
  sampler?: string | null;
  schedule?: string | null;
  seed?: number | null;
  /** WxH, e.g. 1024x1024, both multiples of 16 (default: the model's, or the init picture's aspect) */
  size?: string | null;
  /** image.info's steps: a few-step model (turbo) runs only its own count (6) */
  steps?: number | null;
  /**
   * with image: how far from it (ComfyUI's denoise: the last steps of a round(steps / strength)-step schedule); 0.3-0.6 is the usual img2img range
   * @minimum 0.05
   * @maximum 1
   */
  strength?: number | null;
  /** other keys */
  [key: string]: unknown;
}

/** What image.ocr takes. */
export interface ImageOcrReq {
  /** find blocks set side by side (a gutter between) and read each on its own (default true) */
  columns?: boolean | null;
  /** several pages: each read on its own with its tiles (default true); false: the model's one-pass multi-page reading */
  each_page?: boolean | null;
  /** read the text inside the pictures the model marks (a second pass each; default true) */
  figures?: boolean | null;
  /** the pages, base64, data: URLs or upload:<name> (image.upload), in order: pictures, or PDFs (split into their pages, 150 dpi) */
  images: string[];
  /** default 8192 */
  max_tokens?: number | null;
  /** an OCR model's id (default: the first enabled) */
  model?: string | null;
  /** no n-gram of this many tokens repeated (35; 0: off) */
  ngram?: number | null;
  /** "document parsing." (default), "Free OCR.", "<|grounding|>Convert the document to markdown.", "Parse the figure."; several pages: each page under it, or (each_page false) the model's "Multi page parsing."; a <PAGE> mark before each page */
  prompt?: string | null;
  /** 0 (default): greedy */
  temperature?: number | null;
  /** one page: read its 640-pixel tiles too (default true) */
  tiles?: boolean | null;
  /** other keys */
  [key: string]: unknown;
}

/** What image.upscale makes from: the body its kind's server takes. */
export interface ImageUpscaleBody {
  /** the picture: PNG, JPEG or WebP as base64, a data: URL or upload:<name> (image.upload) */
  image: string;
  /** the model's id; none: the loaded one, else the first enabled */
  model?: string | null;
  /**
   * waifu2x's denoise level (-1: none)
   * @minimum -1
   * @maximum 3
   */
  noise?: number | null;
  response_format?: ResponseFormat | null;
  /** the factor: Real-ESRGAN 2, 3 (animevideov3) or 4; waifu2x 1 (denoise only), 2, 4 ... 32 (its 2x model again each time) */
  scale?: number | null;
  /**
   * the tile's side in input pixels (Real-ESRGAN 200, waifu2x 400 by default: as the ncnn programs)
   * @minimum 32
   */
  tile?: number | null;
  /** the upscaler's model (image.info's upscale list): realesrgan-x4plus (default at 4x), realesr-animevideov3 (default at 2x / 3x), ..., models-cunet (waifu2x's default) */
  variant?: string | null;
  /** other keys */
  [key: string]: unknown;
}

/** What image.vectorize makes from: the body its kind's server takes. */
export interface ImageVectorizeBody {
  /**
   *
   * @minimum 1
   * @maximum 8
   * @default 2
   */
  beams?: number | null;
  /** the picture: PNG, JPEG or WebP as base64, a data: URL or upload:<name> (image.upload) */
  image: string;
  /**
   * the sequence at most as the model counts it (the picture's 257 rows and the prompt first: 5000 leaves 4741 tokens of SVG)
   * @minimum 260
   * @maximum 8192
   * @default 5000
   */
  max_length?: number | null;
  /** the model's id; none: the loaded one, else the first enabled */
  model?: string | null;
  /**
   *
   * @default 1.0
   */
  repetition_penalty?: number | null;
  /**
   * false: the likeliest tokens (beam search, or greedy with beams 1)
   * @default true
   */
  sample?: boolean | null;
  seed?: number | null;
  /**
   *
   * @default 1.0
   */
  temperature?: number | null;
  /**
   *
   * @default 0.9
   */
  top_p?: number | null;
  /** other keys */
  [key: string]: unknown;
}

/** The model and what it takes; while it loads, the model and `loading` only */
export interface Info {
  model: string;
  loading?: boolean | null;
  arch?: string | null;
  /** it takes pictures (edits) */
  edits?: boolean | null;
  /** it reads pictures (an OCR model: the OCR page) */
  reads?: boolean | null;
  /** it takes guidance: cfg above 1 and a negative prompt */
  guidance?: boolean | null;
  /** the grid the picture's sides are multiples of */
  grid?: number | null;
  /** "transparent" gives an alpha channel */
  transparent?: boolean | null;
  /** the schedule's shift can be set */
  shift?: boolean | null;
  /** the aspect ratios and pixel budgets it offers for a size (a size is a budget at a ratio) */
  sizes?: SizesInfo | null;
  /** it takes a negative prompt */
  negative?: boolean | null;
  /** the step count changes the picture (false: a few-step entry runs its own) */
  steps_free?: boolean | null;
  /** it merges per-request LoRAs */
  takes_loras?: boolean | null;
  /** what a reading takes besides the pages and the instruction: tiles, figures, columns, guard, each_page; boxes when it writes them */
  ocr_takes?: string[] | null;
  /** the shortest and longest side it draws */
  min_side?: number | null;
  max_side?: number | null;
  /** the most pixels a picture may have, when the card's room limits it below the longest sides squared */
  max_pixels?: number | null;
  /** the most pictures an edit takes */
  max_pictures?: number | null;
  /** the most pages a reading takes */
  max_pages?: number | null;
  /** an OCR model's instructions */
  prompts?: OcrPromptInfo[] | null;
  defaults?: Defaults | null;
  samplers?: string[] | null;
  schedules?: string[] | null;
  /** the engine's own per-request options (sent as `options`) */
  options?: EngineOptionInfo[] | null;
  loras?: LoraInfo[] | null;
  /** it keeps what it makes (an output directory: links, the history) */
  saves?: boolean | null;
  /** it serves its page */
  wfe?: boolean | null;
  /** it writes pictures as SVG (a vectorizer) */
  vectorize?: boolean | null;
  /** an upscaler's variants (empty: it draws) */
  upscale?: UpscaleInfo[] | null;
}

/** A LoRA registered for the model */
export interface LoraInfo {
  id: string;
  title: string;
  /** the scale it is merged at now; null: not loaded */
  loaded?: number | null;
}

/** A model in OpenAI's list */
export interface ModelEntry {
  id: string;
  /** model */
  object: string;
  owned_by: string;
  created: number;
}

/** OpenAI's list of models: the one this server serves */
export interface ModelList {
  /** list */
  object: string;
  data: ModelEntry[];
}

/** An instruction an OCR model is trained on */
export interface OcrPromptInfo {
  id: string;
  prompt: string;
  /** what it reads */
  title: string;
}

/** A picture made: its link (response_format url) or its PNG (b64_json) */
export interface PictureMade {
  url?: string | null;
  b64_json?: string | null;
  revised_prompt: string;
  seed: number;
  width: number;
  height: number;
}

/** OpenAI's images answer, with how they were made (`nextsycl`: the key nextsycl's contract names it; the front door's methods call it run) */
export interface Pictures {
  created: number;
  data: PictureMade[];
  nextsycl: PicturesRun;
}

/** How pictures were made */
export interface PicturesRun {
  seconds: number;
  steps: number;
  /** the first picture's; the n-th is seed + n */
  seed: number;
  /** name:scale, as merged */
  loras: string[];
  /** the card's energy, watt-hours */
  wh?: number | null;
}

/** What the server is doing: busy false, or what it is making and how far it is */
export interface Progress {
  busy: boolean;
  /** LoRAs being merged (the engine reloaded) */
  loading?: boolean | null;
  prompt?: string | null;
  /** the picture being made (1-based) of `pictures` */
  picture?: number | null;
  pictures?: number | null;
  /** the step (or tile, or token) done of `of` */
  at?: number | null;
  of?: number | null;
  /** what is counted: tiles (an upscale), frames (a clip's), tokens (a vectorize) */
  phase?: string | null;
  /** a reading (OCR): its pages, the text so far and its tokens */
  reading?: boolean | null;
  pages?: number | null;
  text?: string | null;
  tokens?: number | null;
  /** seconds since it started */
  seconds?: number | null;
  /** requests waiting for the engine */
  waiting?: number | null;
  /** the front door's job running, if it named one */
  request_id?: string | null;
}

/** A reading (OCR): the text and how it went */
export interface Reading {
  created: number;
  model: string;
  /** as the model wrote it (its layout markup kept; several pages: a <PAGE> mark before each) */
  text: string;
  prompt: string;
  pages: number;
  tokens: number;
  prompt_tokens: number;
  prompt_seconds: number;
  read_tok_s: number;
  write_seconds: number;
  tok_s: number;
  seconds: number;
  wh?: number | null;
}

/** How a picture comes back: a URL, or the bytes as base64 (OpenAI's names): url | b64_json */
export type ResponseFormat = "url" | "b64_json";

/** The sizes an engine offers: aspect ratios ("W:H") and pixel budgets */
export interface SizesInfo {
  ratios: string[];
  pixels: number[];
}

/** An SVG written */
export interface Svg {
  /** the SVG as the model wrote it (from <svg) */
  svg: string;
  /** </svg> ended it (false: max_length stopped it, an element maybe half written) */
  closed: boolean;
  tokens: number;
}

/** A variant an upscaler offers */
export interface UpscaleInfo {
  variant: string;
  about: string;
  scales: number[];
  /** the denoise levels it takes (empty: none) */
  noise: number[];
}

/** How an upscale went */
export interface UpscaleRun {
  seconds: number;
  /** a picture: its tiles and their side */
  tiles?: number | null;
  tile?: number | null;
  /** a clip: its frames and frames a second made */
  frames?: number | null;
  fps_done?: number | null;
  wh?: number | null;
}

/** A picture or a clip upscaled */
export interface Upscaled {
  created: number;
  data: UpscaledItem[];
  nextsycl: UpscaleRun;
}

/** A picture or a clip upscaled: its link or its bytes (b64_json) */
export interface UpscaledItem {
  width: number;
  height: number;
  variant: string;
  /** the factor made (waifu2x 4x and up: its 2x model again each time) */
  scale: number;
  noise?: number | null;
  url?: string | null;
  b64_json?: string | null;
  /** a clip: its frames, frame rate (as ffprobe gives it, 24/1) and file name */
  frames?: number | null;
  fps?: string | null;
  name?: string | null;
}

/** How an SVG was written */
export interface VectorizeRun {
  seconds: number;
  prompt_seconds: number;
  tokens: number;
  tok_s: number;
  wh?: number | null;
}

/** A picture written as SVG */
export interface Vectorized {
  created: number;
  data: Svg[];
  nextsycl: VectorizeRun;
}

/** What video.upscale makes from: the body its kind's server takes. */
export interface VideoUpscaleBody {
  /**
   * the H.264 encode's quality (lower: better, bigger)
   * @minimum 0
   * @maximum 40
   * @default 16
   */
  crf?: number | null;
  /** or a clip made here (a video.generate clip's name, h3_..., with or without .mp4) */
  file?: string | null;
  /** the model's id; none: the loaded one, else the first enabled */
  model?: string | null;
  /** as image.upscale */
  noise?: number | null;
  /** url (default): the server keeps the MP4 and links it */
  response_format?: ResponseFormat | null;
  /** as image.upscale */
  scale?: number | null;
  /** as image.upscale */
  tile?: number | null;
  /** as image.upscale (realesr-animevideov3: trained on video frames) */
  variant?: string | null;
  /** the clip: MP4 / WebM / MOV ... as base64 or a data: URL */
  video?: string | null;
  /** other keys */
  [key: string]: unknown;
}

/** A route's failure: the words its body's `error` said, and the body. */
export class RouteError extends Error {
  constructor(message: string, readonly body: unknown) {
    super(message);
  }
}

function runtime(base: string, fetcher: typeof fetch) {
  const words = (e: any): string => (typeof e === "string" ? e : (e?.message ?? JSON.stringify(e)));
  const read = async (res: Response, u: string, ownError: boolean): Promise<any> => {
    const text = await res.text();
    let v: any = null;
    try {
      v = text ? JSON.parse(text) : null;
    } catch {
      throw new RouteError(`${u}: the answer is not JSON (HTTP ${res.status})`, text);
    }
    const failed = v !== null && typeof v === "object" && !Array.isArray(v) && v.error != null && (!ownError || v.ok === false);
    if (failed) throw new RouteError(words(v.error), v);
    return v;
  };
  return {
    url(path: string, req: object, query: boolean): string {
      const fields = req as Record<string, unknown>;
      const used = new Set<string>();
      let p = path.replace(/\{([^}]+)\}/g, (_, k: string) => {
        used.add(k);
        return encodeURIComponent(String(fields[k] ?? ""));
      });
      if (query) {
        const q = new URLSearchParams();
        for (const [k, v] of Object.entries(fields)) {
          if (used.has(k) || v === undefined || v === null) continue;
          for (const x of Array.isArray(v) ? v : [v]) q.append(k, String(x));
        }
        const s = q.toString();
        if (s) p += `?${s}`;
      }
      return base + p.slice(1);
    },
    async json(method: string, u: string, body?: BodyInit, type?: string, ownError = false): Promise<any> {
      const res = await fetcher(u, { method, body, headers: type ? { "content-type": type } : undefined });
      return read(res, u, ownError);
    },
    async either(method: string, u: string, body: unknown, ownError = false): Promise<any> {
      const form = body instanceof FormData;
      const res = await fetcher(u, { method, body: form ? body : JSON.stringify(body), headers: form ? undefined : { "content-type": "application/json" } });
      return read(res, u, ownError);
    },
    async blob(method: string, u: string, body?: BodyInit, type?: string): Promise<any> {
      const res = await fetcher(u, { method, body, headers: type ? { "content-type": type } : undefined });
      if ((res.headers.get("content-type") ?? "").startsWith("application/json")) return read(res, u, false);
      return res.blob();
    },
  };
}

export function routes(base = "", fetcher: typeof fetch = (u, i) => fetch(u, i)) {
  const r = runtime(base, fetcher);
  return {
    /**
     * The card: its name, memory, power and temperatures
     * @route GET /api/gpu
     * @tags page
     */
    gpu: (): Promise<Gpu> => r.json("GET", r.url("/api/gpu", {}, true), undefined, undefined, false),
    /**
     * Whether the server answers: ok, or loading (HTTP 503) while its engine loads
     * @route GET /health
     * @tags page
     */
    health: (): Promise<Health> => r.json("GET", r.url("/health", {}, true), undefined, undefined, false),
    /**
     * The model served, as OpenAI lists models
     * @route GET /v1/models
     * @alias /models
     * @tags openai
     */
    models: (): Promise<ModelList> => r.json("GET", r.url("/v1/models", {}, true), undefined, undefined, false),
    /**
     * The model and what it takes: its defaults, samplers, LoRAs, options; an OCR model's instructions, an upscaler's variants
     * @route GET /api/info
     * @tags page
     */
    info: (): Promise<Info> => r.json("GET", r.url("/api/info", {}, true), undefined, undefined, false),
    /**
     * What the server is doing now (the page polls it)
     * @route GET /api/progress
     * @tags page
     */
    progress: (): Promise<Progress> => r.json("GET", r.url("/api/progress", {}, true), undefined, undefined, false),
    /**
     * What the server made, newest first
     * @route GET /api/history
     * @tags page
     */
    history: (): Promise<History> => r.json("GET", r.url("/api/history", {}, true), undefined, undefined, false),
    /**
     * Stops a request: the one named (running or waiting), else the one running
     * @route POST /api/cancel
     * @tags page
     */
    cancel: (req: CancelReq = {}): Promise<Cancelled> => r.json("POST", r.url("/api/cancel", req, false), JSON.stringify(req), "application/json", false),
    /**
     * A picture (or an upscaled clip) an answer links
     * @route GET /v1/images/files/{name}
     * @tags files
     * @produces image/png, video/mp4
     */
    file: (req: FileName): string => r.url("/v1/images/files/{name}", req, true),
    /**
     * Pictures from a prompt (OpenAI's images API, and ours: steps, seed, sampler, schedule, cfg, negative_prompt, loras); an init picture (image) makes it an img2img
     * @route POST /v1/images/generations
     * @alias /images/generations
     * @tags openai
     */
    generations: (req: ImageGenerateBody): Promise<Pictures> => r.json("POST", r.url("/v1/images/generations", req, false), JSON.stringify(req), "application/json", false),
    /**
     * An edit: pictures (up to 8) and the instructions, as OpenAI's multipart form (image, image[] files) or JSON with images (base64 / data URLs)
     * @route POST /v1/images/edits
     * @alias /images/edits
     * @tags openai
     * @body json, multipart
     */
    edits: (body: ImageEditBody | FormData): Promise<Pictures> => r.either("POST", r.url("/v1/images/edits", {}, true), body, false),
    /**
     * A picture written as SVG by a vectorizer (StarVector)
     * @route POST /v1/images/vectorize
     * @tags openai
     */
    vectorize: (req: ImageVectorizeBody): Promise<Vectorized> => r.json("POST", r.url("/v1/images/vectorize", req, false), JSON.stringify(req), "application/json", false),
    /**
     * A picture upscaled (Real-ESRGAN, waifu2x): a link, or the PNG as base64
     * @route POST /v1/images/upscale
     * @tags openai
     */
    upscale: (req: ImageUpscaleBody): Promise<Upscaled> => r.json("POST", r.url("/v1/images/upscale", req, false), JSON.stringify(req), "application/json", false),
    /**
     * A clip upscaled frame by frame (ffmpeg decodes and encodes, the audio copied): the MP4 linked, or as base64
     * @route POST /v1/videos/upscale
     * @tags openai
     */
    upscaleVideo: (req: VideoUpscaleBody = {}): Promise<Upscaled> => r.json("POST", r.url("/v1/videos/upscale", req, false), JSON.stringify(req), "application/json", false),
    /**
     * Pages read (an OCR model): pictures or PDFs, the text as the model writes it
     * @route POST /v1/ocr
     * @tags openai
     */
    ocr: (req: ImageOcrReq): Promise<Reading> => r.json("POST", r.url("/v1/ocr", req, false), JSON.stringify(req), "application/json", false),
  };
}
